mkdir -p out && cat > out/t.mjs <<'E'
import l from 'lodash/kebabCase.js';
import a from 'es-toolkit/string';
import {kebabCase as c, toNumber as cn} from 'es-toolkit/compat';
import tl from 'lodash/toNumber.js';
const ch='aBZ9 1-_.xyzQ';
let bad={m:0,c:0},n=0,bn={c:0};
for(let i=0;i<30000;i++){let s='';const L=Math.random()*40|0;for(let j=0;j<L;j++)s+=ch[Math.random()*ch.length|0];
 n++; if(l(s)!==a.kebabCase(s))bad.m++; if(l(s)!==c(s))bad.c++;}
const ch2='0123.+- ex';
for(let i=0;i<30000;i++){let s='';const L=Math.random()*8|0;for(let j=0;j<L;j++)s+=ch2[Math.random()*ch2.length|0];
 if(Object.is(tl(s),cn(s))===false)bn.c++;}
console.log(bad,bn, Object.keys(a).filter(k=>/umber/.test(k)));
E
cp out/t.mjs ./t.mjs; node t.mjs; rm t.mjs; ls node_modules | head;

